#include "Dsp.h"
#include <vector>
#include <cmath>
#include <iostream>
#include <stdexcept>
namespace {void check(bool b,const char* text){if(!b)throw std::runtime_error(text);}vocal::VocalParameters flat(){vocal::VocalParameters p;p.highPassHz=40;p.warmthDb=p.presenceDb=p.deEss=p.deharsh=p.reverb=p.delay=p.makeupDb=0;p.thresholdDb=0;p.ratio=1;return p;}double tone(double hz,float amplitude,vocal::VocalParameters p,double* distortion=nullptr){vocal::VocalChain chain;chain.prepare(48000);chain.setParameters(p);double power=0,s=0,c=0;std::vector<float> last(48000);for(int i=0;i<48000*7;++i){float l=amplitude*static_cast<float>(std::sin(2*vocal::pi*hz*i/48000)),r=l;chain.processDry(l,r);check(std::isfinite(l)&&std::abs(l-r)<1e-6,"linked stereo and finite");if(i>=48000*6){const int n=i-48000*6;last[n]=l;power+=l*l;s+=l*std::sin(2*vocal::pi*hz*i/48000);c+=l*std::cos(2*vocal::pi*hz*i/48000);}}if(distortion){double residual=0;for(int i=0;i<48000;++i){const double fitted=2*(s*std::sin(2*vocal::pi*hz*i/48000)+c*std::cos(2*vocal::pi*hz*i/48000))/48000;residual+=std::pow(last[i]-fitted,2);}*distortion=std::sqrt(residual/power);}return std::sqrt(power/48000);}}
int main(){try{auto base=flat(),leveled=base;leveled.leveling=1;const double quiet=tone(220,.025f,leveled),loud=tone(220,.25f,leveled);const double gap=20*std::log10(loud/quiet);std::cout<<"phrase RMS gap: "<<gap<<" dB from 20 dB input\n";check(gap>8&&gap<13,"leveler reduces phrase gap without flattening everything");double thd=0;tone(220,.025f,leveled,&thd);std::cout<<"steady tone residual: "<<thd<<"\n";check(thd<.001,"leveling must not audibly distort a steady voice fundamental");auto tame=base;tame.dynamicTame=1;const double lowDb=20*std::log10(tone(220,.1f,tame)/tone(220,.1f,base)),highDb=20*std::log10(tone(3500,.1f,tame)/tone(3500,.1f,base));std::cout<<"tame low/high: "<<lowDb<<" / "<<highDb<<" dB\n";check(std::abs(lowDb)<.3&&highDb<-3&&highDb>-9,"dynamic tame targets harsh band while preserving low voice");
    vocal::VocalChain noise;noise.prepare(48000);noise.setParameters(leveled);double energy=0;for(int i=0;i<48000*10;++i){const float amplitude=i<48000*7?.025f:.0001f;float l=amplitude*static_cast<float>(std::sin(2*vocal::pi*(i<48000*7?220:1100)*i/48000)),r=l;noise.processDry(l,r);if(i>=48000*9)energy+=l*l;}const double floorGain=20*std::log10(std::sqrt(energy/48000)/(.0001/std::sqrt(2.0)));std::cout<<"noise floor gain: "<<floorGain<<" dB\n";check(floorGain<.5,"leveler must release boost during pauses instead of raising background noise");
    auto wet=flat();wet.reverb=.3f;wet.decaySeconds=1.3;wet.preDelayMs=20;auto ducked=wet;ducked.reverbDuck=1;vocal::VocalChain a,b;a.prepare(48000);b.prepare(48000);a.setParameters(wet);b.setParameters(ducked);double activeA=0,activeB=0,tailA=0,tailB=0;for(int i=0;i<48000*3;++i){const float x=i<48000?.25f*static_cast<float>(std::sin(2*vocal::pi*220*i/48000)):0;float la=x,ra=x,lb=x,rb=x;a.processAmbience(la,ra);b.processAmbience(lb,rb);if(i>24000&&i<48000){activeA+=std::pow(la-x*(1-wet.reverb*.3f),2);activeB+=std::pow(lb-x*(1-wet.reverb*.3f),2);}if(i>48000*2){tailA+=la*la;tailB+=lb*lb;}}std::cout<<"duck active/tail ratios: "<<activeB/activeA<<" / "<<tailB/tailA<<"\n";check(activeB<activeA*.6&&tailB>tailA*.8,"room return ducks during singing and recovers its natural tail");
    {vocal::VocalChain switcher;switcher.prepare(48000);auto p=flat();p.dynamicTame=1;switcher.setParameters(p);float previous=0;for(int i=0;i<48000*2;++i){float l=.2f*static_cast<float>(std::cos(2*vocal::pi*3500*i/48000)),r=l;switcher.processDry(l,r);previous=l;}p.dynamicTame=0;switcher.setParameters(p);float l=.2f,r=l;switcher.processDry(l,r);check(std::abs(l-previous)<.05f,"tame bypass must fade instead of jumping harsh-band gain in one sample");}
    auto bypass=vocal::preset(4);bypass.bypass=true;vocal::VocalChain dry;dry.prepare(44100);dry.setParameters(bypass);float l=.123f,r=-.321f;dry.process(l,r);check(l==.123f&&r==-.321f,"global bypass remains exact with all new stages enabled");std::cout<<"PASS: leveling, harmonic purity, selective taming, pause noise, wet duck/tail and bypass\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
